CREATE TABLE responsibilities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,conversation_id uuid NOT NULL,vm_id uuid NOT NULL,client_responsibility_id uuid NOT NULL,source_message_id uuid NOT NULL,source_quote text NOT NULL,objective text NOT NULL,trigger jsonb NOT NULL,notification_mode text NOT NULL CHECK(notification_mode IN ('enabled','quiet')),quiet_hours jsonb,state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','complete','cancelled')),next_review_at timestamptz NOT NULL DEFAULT now(),last_evaluated_at timestamptz,last_context_hash text,last_error text,failure_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),UNIQUE(workspace_id,client_responsibility_id),FOREIGN KEY(workspace_id,conversation_id) REFERENCES conversations(workspace_id,id),FOREIGN KEY(workspace_id,vm_id) REFERENCES vms(workspace_id,id),FOREIGN KEY(workspace_id,source_message_id) REFERENCES messages(workspace_id,id));
CREATE INDEX responsibilities_due ON responsibilities(vm_id,next_review_at) WHERE state='active';
CREATE TABLE responsibility_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,responsibility_id uuid NOT NULL,context_hash text NOT NULL,outcome text NOT NULL CHECK(outcome IN ('quiet','notify','complete')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,responsibility_id,context_hash),FOREIGN KEY(workspace_id,responsibility_id) REFERENCES responsibilities(workspace_id,id));
CREATE TABLE responsibility_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,responsibility_id uuid NOT NULL,context_hash text NOT NULL,content text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','delivered','cancelled')),message_id uuid,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,UNIQUE(workspace_id,responsibility_id,context_hash),FOREIGN KEY(workspace_id,responsibility_id) REFERENCES responsibilities(workspace_id,id),FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id));
